/**
 * Cross-check the TypeScript implementation against the verified Python
 * reference workbook (reference/uae_lottery_luckyday_results.xlsx).
 *
 * The workbook generated by the web app from public/data/luckyday.json must
 * match the reference cell for cell on every sheet except Metadata, whose
 * timestamps differ. The reference only covers draws up to the date it was
 * made, so draws newer than its latest one are left out of the comparison.
 *
 *   npm run verify:reference
 */
import ExcelJS from 'exceljs'
import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { buildWorkbookBuffer } from '../src/lib/xlsx.ts'
import { parseSnapshot } from '../src/lib/snapshot.ts'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const snap = parseSnapshot(JSON.parse(readFileSync(resolve(root, 'public/data/luckyday.json'), 'utf8')))

type Grid = Map<string, unknown[][]>

async function readGrid(source: string | ArrayBuffer): Promise<Grid> {
  const wb = new ExcelJS.Workbook()
  if (typeof source === 'string') await wb.xlsx.readFile(source)
  else await wb.xlsx.load(source)
  const out: Grid = new Map()
  wb.eachSheet((ws) => {
    const rows: unknown[][] = []
    ws.eachRow({ includeEmpty: true }, (row) => {
      const vals = (row.values as unknown[]).slice(1)
      rows.push(vals.map((v) => (v instanceof Date ? v.toISOString().slice(0, 16) : v ?? null)))
    })
    out.set(ws.name, rows)
  })
  return out
}

const ref = await readGrid(resolve(root, 'reference/uae_lottery_luckyday_results.xlsx'))
const refResults = ref.get('Results')!
const refDrawNos = new Set(refResults.slice(1).map((r) => String(r[0])))
const refLatestSeq = refResults.length - 1
const draws = snap.draws.filter((d) => refDrawNos.has(d.drawNo))
console.log(`Snapshot: ${snap.drawCount} draws; reference: ${refDrawNos.size} draws; comparing ${draws.length}.`)

const missingFromSnapshot = [...refDrawNos].filter((n) => !snap.draws.some((d) => d.drawNo === n))
const errors: string[] = []
if (missingFromSnapshot.length) errors.push(`draws in reference but not in snapshot: ${missingFromSnapshot.join(', ')}`)
if (draws.length !== refLatestSeq) errors.push(`draw count ${draws.length} != reference ${refLatestSeq}`)

const mine = await readGrid(await buildWorkbookBuffer(draws, { generatedAt: '1970-01-01 00:00:00', generator: 'verify' }))
const names = [...ref.keys()]
if (JSON.stringify(names) !== JSON.stringify([...mine.keys()])) errors.push(`sheet names differ: ${[...mine.keys()]} vs ${names}`)

const same = (a: unknown, b: unknown) =>
  a === b || (a == null && b == null) ||
  (typeof a === 'number' && typeof b === 'number' && Math.abs(a - b) < 1e-9) ||
  String(a) === String(b)

for (const name of names) {
  if (name === 'Metadata') continue
  const a = ref.get(name)!
  const b = mine.get(name) ?? []
  if (a.length !== b.length) errors.push(`${name}: ${b.length} rows vs reference ${a.length}`)
  let diffs = 0
  for (let r = 0; r < Math.max(a.length, b.length); r++) {
    const ra = a[r] ?? [], rb = b[r] ?? []
    for (let c = 0; c < Math.max(ra.length, rb.length); c++) {
      if (!same(ra[c] ?? null, rb[c] ?? null)) {
        if (diffs++ < 5) errors.push(`${name} R${r + 1}C${c + 1}: web=${JSON.stringify(rb[c])} reference=${JSON.stringify(ra[c])}`)
      }
    }
  }
  console.log(`${diffs ? 'DIFF' : 'OK  '} ${name} (${a.length - 1} data rows${diffs ? `, ${diffs} differing cells` : ''})`)
}

if (errors.length) {
  console.error('\nReference check FAILED:\n' + errors.map((e) => ' - ' + e).join('\n'))
  process.exit(1)
}
console.log('\nReference check passed: web workbook matches the Python reference.')
